-- 91_DIAGNOSE_CLOUD_SQL_ERROR.sql — DMF0053 클라우드 "조회 시 SQL ERROR" 진단 (SCM_MGR, 읽기 전용). ① 이 곧 정답.
-- 사내 기대값: API 4 / PROC_M 인자 {'DMF0002_GET_TITLESET_POPUP': 7, 'PKG_DMF0053.P_DMF0053_GET_CUST_FCST_WATERFALL': 25, 'PKG_DMF0053.P_DMF0053_GET_SPREAD_TITLE': 9, 'SCM0002_SET_TITLESET_POPUP': 14} / GTT 17 / SHEET_COLUMNS [('CUST Fcst Waterfall', 66)] / SHEET_MEASURE 2

-- ① 실패 직후 SP 예외 로그 (SQL_ERR_CODE + BACKTRACE 라인) — 0건이면 SP 진입 전 실패(권한/시노님/인자/BE)
SELECT PROGRAM_NAME, LOG_TYPE, TO_CHAR(EVENT_DATE,'MM-DD HH24:MI:SS') DT, SQL_ERR_CODE, SUBSTR(SQL_ERR_MSG,1,300) ERR, SUBSTR(SQL_BACKTRACE,1,200) BT, SUBSTR(LOG_MESSAGE,1,80) MSG
  FROM SCM_MGR.SCM_SYS_LOG_BATCH WHERE PROGRAM_NAME LIKE '%DMF0053%' AND EVENT_DATE > SYSDATE - 1/24 ORDER BY EVENT_DATE DESC FETCH FIRST 15 ROWS ONLY;

-- ② 객체 상태 (기대 전부 VALID) + 컴파일 오류
SELECT OBJECT_NAME, OBJECT_TYPE, STATUS, TO_CHAR(LAST_DDL_TIME,'MM-DD HH24:MI') LDDL FROM ALL_OBJECTS WHERE OWNER='SCM_MGR' AND OBJECT_NAME IN ('DMF0002_GET_TITLESET_POPUP','PKG_DMF0053','SCM0002_SET_TITLESET_POPUP','PKG_DMF0053','FN_GET_DM_MKT_OWNER_NAME','FN_STRING_SPLIT','UF_FX_STRING_SPLIT') ORDER BY 1,2;
SELECT NAME, TYPE, LINE, TEXT FROM ALL_ERRORS WHERE OWNER='SCM_MGR' AND NAME IN ('DMF0002_GET_TITLESET_POPUP','PKG_DMF0053','SCM0002_SET_TITLESET_POPUP','PKG_DMF0053') ORDER BY 1,2,SEQUENCE;

-- ③ GTT (기대 17: ['GT_DM53_CALENDAR', 'GT_DM53_COLUMN_SETUP', 'GT_DM53_EDI_CALLOFF', 'GT_DM53_ITEM_SINGLE_V', 'GT_DM53_ITEM_SINGLE_VT', 'GT_DM53_RAW_DATA', 'GT_DM53_SCM_MST_SITE', 'GT_DM53_SITE_ITEM', 'GT_DMF0053_COLUMN_SETUP', 'GT_DMF0053_EDI_CALLOFF', 'GT_DMF0053_ITEM_SINGLE_V', 'GT_DMF0053_ITEM_SINGLE_V_T', 'GT_DMF0053_RAW_DATA', 'GT_DMF0053_SCM_MST_SITE', 'GT_DMF0053_SCM_MST_SITE_ITEM', 'GT_DMF0053_SELECT_MEASURE', 'GT_DMF0053_T'])
SELECT TABLE_NAME FROM ALL_TABLES WHERE OWNER='SCM_MGR' AND TEMPORARY='Y' AND (TABLE_NAME LIKE 'GT_DM53%' OR TABLE_NAME LIKE 'GT_DMF0053%') ORDER BY 1;

-- ④ 앱 계정 EXECUTE + 시노님 (기대: 객체별 SCMP_APP 1행씩 — 없으면 40_GRANT_SYNONYM.sql)
SELECT GRANTEE, TABLE_NAME, PRIVILEGE FROM ALL_TAB_PRIVS WHERE TABLE_SCHEMA='SCM_MGR' AND TABLE_NAME IN ('DMF0002_GET_TITLESET_POPUP','PKG_DMF0053','SCM0002_SET_TITLESET_POPUP','PKG_DMF0053') AND GRANTEE IN ('SCMP_APP','SCMD_APP') ORDER BY 2,1;
SELECT OWNER, SYNONYM_NAME FROM ALL_SYNONYMS WHERE TABLE_OWNER='SCM_MGR' AND SYNONYM_NAME IN ('DMF0002_GET_TITLESET_POPUP','PKG_DMF0053','SCM0002_SET_TITLESET_POPUP','PKG_DMF0053') AND OWNER IN ('SCMP_APP','SCMD_APP') ORDER BY 2,1;

-- ⑤ 배선 계약 PROC_M 인자 수 vs 실제 (기대 양쪽 동일: {'DMF0002_GET_TITLESET_POPUP': 7, 'PKG_DMF0053.P_DMF0053_GET_CUST_FCST_WATERFALL': 25, 'PKG_DMF0053.P_DMF0053_GET_SPREAD_TITLE': 9, 'SCM0002_SET_TITLESET_POPUP': 14})
SELECT P.PROC_NM, COUNT(*) PROC_M_CNT,
       (SELECT COUNT(*) FROM ALL_ARGUMENTS A WHERE A.OWNER='SCM_MGR' AND A.ARGUMENT_NAME IS NOT NULL
          AND CASE WHEN A.PACKAGE_NAME IS NULL THEN A.OBJECT_NAME ELSE A.PACKAGE_NAME||'.'||A.OBJECT_NAME END = P.PROC_NM) ARG_CNT
  FROM SCM_MGR.SCM_ADM_PROC_M P WHERE P.PROC_NM IN (SELECT API_URL FROM SCM_MGR.SCM_ADM_API_M WHERE API_ID LIKE 'DMF0053%') GROUP BY P.PROC_NM;
SELECT API_ID, API_TP_CD, API_URL, USE_YN FROM SCM_MGR.SCM_ADM_API_M WHERE API_ID LIKE 'DMF0053%';

-- ⑥ 시트 메타 (기대 SHEET_COLUMNS [('CUST Fcst Waterfall', 66)] / MEASURE 2) — SP 가 이 메타로 동적 SELECT 를 만든다
SELECT SHEET_NAME, COUNT(*) FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='DMF0053' GROUP BY SHEET_NAME;
SELECT COUNT(*) FROM SCM_MGR.SCM_MST_SHEET_MEASURE WHERE PROGRAM_ID='DMF0053';

-- ⑦ C_DATA 적재 (DM_PLN_CUST_FCST_H.CREATION_DATE 가 조회 기준) — 0 이면 C_DATA 로더 미실행
SELECT COUNT(*) TOTAL, COUNT(CREATION_DATE) WITH_CDATE, TO_CHAR(MAX(CREATION_DATE),'YYYY-MM-DD') MAXC FROM SCM_MGR.DM_PLN_CUST_FCST_H;

-- ⑧ 세션 NLS (클라우드 BE 세션 기준 비교용)
SELECT PARAMETER, VALUE FROM NLS_DATABASE_PARAMETERS WHERE PARAMETER IN ('NLS_DATE_FORMAT','NLS_LANGUAGE','NLS_TERRITORY');
